function eh(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function enquiry_finish(string $message): never { $_SESSION['admin_notice']=$message; header('Location: enquiries.php'); exit; }
function enquiry_id(): int { return (int)(filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:0); }
function enquiry_input(bool $new): array {
    $row=['name'=>trim((string)($_POST['name']??'')),'phone'=>trim((string)($_POST['phone']??'')),'email'=>trim((string)($_POST['email']??'')),'event_type'=>trim((string)($_POST['event_type']??'')),'hall'=>strtolower(trim((string)($_POST['hall']??''))),'event_date'=>trim((string)($_POST['event_date']??'')),'guests'=>trim((string)($_POST['guests']??'')),'source'=>strtolower(trim((string)($_POST['source']??'other'))),'message'=>trim((string)($_POST['message']??''))];
    $validDate=preg_match('/^\d{4}-\d{2}-\d{2}$/',$row['event_date'])&&(!$new||booking_valid_date($row['event_date']));
    if($row['name']===''||admin_text_length($row['name'])>120||!preg_match('/^[0-9+() -]{10,18}$/',$row['phone'])||($row['email']!==''&&(!filter_var($row['email'],FILTER_VALIDATE_EMAIL)||admin_text_length($row['email'])>254))||$row['event_type']===''||admin_text_length($row['event_type'])>40||!$validDate||($row['guests']!==''&&(!ctype_digit($row['guests'])||(int)$row['guests']<1||(int)$row['guests']>10000))||!in_array($row['source'],ENQUIRY_SOURCES,true)||admin_text_length($row['message'])>2000) throw new InvalidArgumentException('Check the enquiry details and try again.');
    $row['guests']=$row['guests']===''?null:(int)$row['guests']; if(!in_array($row['hall'],ADMIN_HALLS,true)) throw new InvalidArgumentException('Choose a valid hall.'); return $row;
}
try { $config=booking_config(); $db=booking_db(); $passwordHash=(string)($config['admin_password_hash']??''); } catch(Throwable $error){ http_response_code(503); exit('Booking admin is not configured yet.'); }
$loggedIn=($_SESSION['password_hash']??null)===$passwordHash; if(!$loggedIn){header('Location: index.php');exit;}
$_SESSION['csrf']??=bin2hex(random_bytes(32)); $notice=(string)($_SESSION['admin_notice']??''); unset($_SESSION['admin_notice']); $schemaReady=enquiry_schema_ready($db);
if($_SERVER['REQUEST_METHOD']==='POST'){
    $ajax=($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='XMLHttpRequest';
    if(!hash_equals((string)$_SESSION['csrf'],(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid form token.');}
    if(!$schemaReady) enquiry_finish('Run the enquiries database migration first.');
    $action=(string)($_POST['action']??'');
    try{
        if($action==='new_enquiry'){
            $row=enquiry_input(true); $followup=admin_valid_datetime(trim((string)($_POST['follow_up_at']??''))); $note=trim((string)($_POST['internal_note']??'')); if(admin_text_length($note)>5000)throw new InvalidArgumentException('Note is too long.');
            $db->beginTransaction(); $insert=$db->prepare("INSERT INTO bookings(name,phone,email,event_type,hall,event_date,guests,message,status,record_type,source) VALUES(?,?,?,?,?,?,?,?,'pending','enquiry',?)"); $insert->execute([$row['name'],$row['phone'],$row['email'],$row['event_type'],$row['hall'],$row['event_date'],$row['guests'],$row['message'],$row['source']]); $id=(int)$db->lastInsertId(); admin_activity($db,$id,'enquiry_created','Enquiry created by Admin for '.ucfirst($row['hall']).' Hall');
            if($followup){$q=$db->prepare('INSERT INTO enquiry_followups(enquiry_id,scheduled_at) VALUES(?,?)');$q->execute([$id,$followup]);$db->prepare("UPDATE bookings SET follow_up_at=?,status='follow_up' WHERE id=?")->execute([$followup,$id]);admin_activity($db,$id,'followup_created','Follow-up scheduled for '.$followup);}
            if($note!==''){$q=$db->prepare('INSERT INTO enquiry_notes(enquiry_id,note,author) VALUES(?,?,?)');$q->execute([$id,$note,'Admin']);admin_activity($db,$id,'note_added','Internal note added');}
            $db->commit(); enquiry_finish('New enquiry ENQ-'.str_pad((string)$id,6,'0',STR_PAD_LEFT).' created.');
        }
        if($action==='edit_enquiry'){
            $id=enquiry_id();$row=enquiry_input(false);$status=(string)($_POST['status']??'pending');if(!$id||!in_array($status,ENQUIRY_STATUSES,true)||in_array($status,['converted'],true))throw new InvalidArgumentException('Invalid enquiry update.');
            $before=$db->prepare("SELECT status FROM bookings WHERE id=? AND record_type='enquiry'");$before->execute([$id]);$old=$before->fetchColumn();if($old===false)throw new RuntimeException('Enquiry not found.');
            $q=$db->prepare("UPDATE bookings SET name=?,phone=?,email=?,event_type=?,hall=?,event_date=?,guests=?,source=?,message=?,status=? WHERE id=? AND record_type='enquiry' AND status<>'converted'");$q->execute([$row['name'],$row['phone'],$row['email'],$row['event_type'],$row['hall'],$row['event_date'],$row['guests'],$row['source'],$row['message'],$status,$id]);admin_activity($db,$id,'enquiry_edited','Guest, hall or event details updated');if($old!==$status)admin_activity($db,$id,'status_changed','Status changed from '.$old.' to '.$status);enquiry_finish('Enquiry updated.');
        }
        if($action==='set_followup'){
            $id=enquiry_id();$when=admin_valid_datetime(trim((string)($_POST['follow_up_at']??'')));if(!$id||!$when)throw new InvalidArgumentException('Choose a valid follow-up date and time.');
            $db->beginTransaction();$q=$db->prepare('INSERT INTO enquiry_followups(enquiry_id,scheduled_at) SELECT id,? FROM bookings WHERE id=? AND record_type=\'enquiry\' AND status NOT IN(\'converted\',\'cancelled\')');$q->execute([$when,$id]);if(!$q->rowCount())throw new RuntimeException('Active enquiry not found.');$db->prepare("UPDATE bookings SET follow_up_at=?,follow_up_completed_at=NULL,status='follow_up' WHERE id=?")->execute([$when,$id]);admin_activity($db,$id,'followup_created','Follow-up scheduled for '.$when);$db->commit();enquiry_finish('Follow-up scheduled.');
        }
        if($action==='complete_followup'){
            $id=enquiry_id();$q=$db->prepare('UPDATE enquiry_followups SET completed_at=CURRENT_TIMESTAMP WHERE enquiry_id=? AND completed_at IS NULL');$q->execute([$id]);$db->prepare('UPDATE bookings SET follow_up_completed_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$id]);if($q->rowCount())admin_activity($db,$id,'followup_completed','Follow-up marked complete');enquiry_finish($q->rowCount()?'Follow-up completed.':'No open follow-up found.');
        }
        if($action==='add_note'){
            $id=enquiry_id();$note=trim((string)($_POST['note']??''));if(!$id||$note===''||admin_text_length($note)>5000)throw new InvalidArgumentException('Enter a note up to 5,000 characters.');$q=$db->prepare("INSERT INTO enquiry_notes(enquiry_id,note,author) SELECT id,?,'Admin' FROM bookings WHERE id=? AND record_type='enquiry'");$q->execute([$note,$id]);if(!$q->rowCount())throw new RuntimeException('Enquiry not found.');admin_activity($db,$id,'note_added','Internal note added');enquiry_finish('Note added.');
        }
        if($action==='convert'){$bookingId=admin_convert_enquiry($db,enquiry_id());enquiry_finish('Converted to booking VCM-'.str_pad((string)$bookingId,6,'0',STR_PAD_LEFT).'.');}
        if($action==='cancel'){$id=enquiry_id();$q=$db->prepare("UPDATE bookings SET status='cancelled',booked_date=NULL WHERE id=? AND record_type='enquiry' AND status NOT IN('converted','cancelled')");$q->execute([$id]);if($q->rowCount())admin_activity($db,$id,'cancelled','Enquiry cancelled');enquiry_finish($q->rowCount()?'Enquiry cancelled.':'Enquiry could not be cancelled.');}
        if($action==='send_email'){
            $id=enquiry_id();$q=$db->prepare("SELECT * FROM bookings WHERE id=? AND record_type='enquiry'");$q->execute([$id]);$row=$q->fetch();$from=(string)(($config['email_from']??'')?:'bookings@venutaihall.com');if(!$row||!filter_var($row['email'],FILTER_VALIDATE_EMAIL)||!filter_var($from,FILTER_VALIDATE_EMAIL))throw new RuntimeException('A valid guest and sender email are required.');$subject='Venue enquiry ENQ-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$body="Hello {$row['name']},\n\nWe are following up about your {$row['event_type']} enquiry for {$row['event_date']}. Please reply or call us to continue.\n\nLate Venutai Chavan Multipurpose Hall";$sent=mail($row['email'],$subject,$body,['From'=>$from,'Reply-To'=>$from,'Content-Type'=>'text/plain; charset=UTF-8']);admin_activity($db,$id,$sent?'email_sent':'email_failed',$sent?'Reminder accepted by mail server':'Reminder email failed');enquiry_finish($sent?'Email sent to the mail server.':'Email could not be sent.');
        }
        if($action==='track_whatsapp'){$id=enquiry_id();$q=$db->prepare("SELECT 1 FROM bookings WHERE id=? AND record_type='enquiry'");$q->execute([$id]);if(!$q->fetchColumn())throw new RuntimeException('Enquiry not found.');admin_activity($db,$id,'whatsapp_action','WhatsApp reminder opened');header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;}
    }catch(Throwable $error){if($db->inTransaction())$db->rollBack();error_log('Enquiries admin: '.$error->getMessage());if($ajax){http_response_code(422);header('Content-Type: application/json');echo json_encode(['error'=>$error->getMessage()]);exit;}enquiry_finish($error instanceof InvalidArgumentException||$error instanceof RuntimeException?$error->getMessage():'The change could not be saved.');}
}
$filters=enquiry_filters($_GET);$page=max(1,(int)($_GET['page']??1));$perPage=settings_schema_ready($db)?max(10,min(100,(int)setting($db,'items_per_page','20'))):20;$rows=[];$summary=[];$counts=[];$related=['notes'=>[],'followups'=>[],'activity'=>[],'bookings'=>[]];$eventTypes=[];$total=0;
if($schemaReady){$rows=enquiry_rows($db,$filters,$page,$perPage,isset($_GET['export']));if(($_GET['export']??'')==='excel')enquiry_excel($rows);if(($_GET['export']??'')==='pdf')enquiry_pdf($rows);$summary=enquiry_summary($db);$counts=enquiry_tab_counts($db);$total=enquiry_total($db,$filters);$related=enquiry_related($db,$rows);$eventTypes=$db->query("SELECT DISTINCT event_type FROM bookings WHERE record_type='enquiry' ORDER BY event_type")->fetchAll(PDO::FETCH_COLUMN);}
$labels=['pending'=>'New','in_discussion'=>'In Discussion','quote_sent'=>'Quote Sent','follow_up'=>'Follow-up','converted'=>'Converted','cancelled'=>'Cancelled'];$sourceLabels=['website'=>'Website','instagram'=>'Instagram','whatsapp'=>'WhatsApp','phone'=>'Phone','walk-in'=>'Walk-in','other'=>'Other'];$pages=max(1,(int)ceil($total/$perPage));$baseQuery=array_filter($filters,static fn($v)=>$v!=='');$json=['rows'=>$rows,'notes'=>$related['notes'],'followups'=>$related['followups'],'activity'=>$related['activity'],'bookings'=>$related['bookings'],'csrf'=>$_SESSION['csrf']];
