?=$overdue?'overdue':''?>"><?=eh(date('d M Y',strtotime($row['latest_followup_at'])))?></strong><small><?=eh(date('g:i A',strtotime($row['latest_followup_at'])))?><?=$overdue?' · Overdue':''?></small><?php else:?><span class="muted">Not set</span><?php endif;?></td><td data-label="Actions"><div class="row-actions"><a class="whatsapp-action" data-wa-id="<?=eh($row['id'])?>" href="<?=eh($wa)?>" target="_blank" rel="noopener">WA</a><a class="call-action" href="tel:<?=eh($row['phone'])?>">Call</a><button class="view-button" type="button" data-view-enquiry="<?=eh($row['id'])?>">View</button><details><summary>•••</summary><div><button type="button" data-view-enquiry="<?=eh($row['id'])?>" data-target-tab="details">Edit Enquiry</button><button type="button" data-view-enquiry="<?=eh($row['id'])?>" data-target-tab="details">Set Follow-up</button><button type="button" data-view-enquiry="<?=eh($row['id'])?>" data-target-tab="notes">Add Note</button><form method="post"><input type="hidden" name="csrf" value="<?=eh($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=eh($row['id'])?>"><button name="action" value="send_email">Send Email</button></form><?php if(!in_array($row['status'],['converted','cancelled'],true)):?><form method="post"><input type="hidden" name="csrf" value="<?=eh($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=eh($row['id'])?>"><button name="action" value="convert">Convert to Booking</button></form><form method="post"><input type="hidden" name="csrf" value="<?=eh($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=eh($row['id'])?>"><button class="danger-link" name="action" value="cancel">Cancel Enquiry</button></form><?php endif;?></div></details></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="11" class="empty-state"><strong>No enquiries found</strong><span>Change filters or add a new enquiry.</span></td></tr><?php endif;?></tbody></table></div>
